-- תוספות ממצגת הוועדה לשימור אתרים 2016 (public/docs/committee-2016.pdf)
-- עדכוני אתרים (נוצר מ-lib/demo/buildings.ts: node --experimental-strip-types scripts/gen-sites-sql.mts 14,17,19,25,26,28,30,31),
-- תמונות מהמצגת, שילוב האתרים החדשים במסלולים ומסלולים 6–9. תוספת בלבד: מיקומי תחנות קיימים לא משתנים.

CREATE TABLE IF NOT EXISTS shimur_buildings_backup_20261013b AS SELECT * FROM shimur_buildings;
ALTER TABLE shimur_buildings_backup_20261013b ENABLE ROW LEVEL SECURITY;
CREATE TABLE IF NOT EXISTS shimur_route_sites_backup_20261013 AS SELECT * FROM shimur_route_sites;
ALTER TABLE shimur_route_sites_backup_20261013 ENABLE ROW LEVEL SECURITY;

INSERT INTO shimur_buildings (site_no, city_registry_id, name, address, neighborhood, parcel, is_complex, lat, lng, year_built, year_built_verified, architect, architect_verified, style, historical_periods, protection_level, documentation_reason, owner, current_use, building_type, preservation_reasons, priority_level, full_description, additional_info, iaa_reference, gov_sources, committee_no, list_status, statutory_ref, coords_approx, data_conflict, components, risk_note, grade_note) VALUES
(14, 'ASH-014', 'מצודת אשדוד ים', 'חוף י״א — אשדוד ים', 'חוף הים', NULL, false, 31.7803, 34.6217, NULL, false, NULL, false, 'מצודה ארכאולוגית', ARRAY['תקופת הברזל','תקופה פרסית-הלניסטית','תקופה ביזנטית','תקופה אסלאמית קדומה']::text[], 'א', 'ארכאולוגית, נופית', 'ממ"י / עיריית אשדוד', 'קיים - טיילת חוף', 'מצודה ארכאולוגית', ARRAY['ארכאולוגית','נופית','אקולוגית']::text[], 'גבוהה', 'מבצר אומיי מסוף המאה ה-7 או המאה ה-8 (כ-60×40 מ׳), חלק משרשרת מבצרי חוף (רבאטאת). באתר הסמוך — ביצורי תקופת הברזל (המאה ה-8 לפנה"ס) ושרידים הלניסטיים. חפירות רשות העתיקות בשנים 1997–1999.', 'הוקמה לפני 1700, ולכן אינה "אתר לשימור" לפי התוספת הרביעית לחוק. בשל חשיבותה הוסדרה לשימור בתב"ע 122/101/02/3 ובתכנית האסטרטגית לטיילת החוף, ליעודי הקרקע לרווחת הציבור, הנחיות לשימור והקשר עם הסביבה החופית. המצודה היא חלק מהמרחב העירוני הימי בקטע הדרומי של העיר. לפי מצגת הוועדה: בתקופה הרומית והביזנטית (המאות 1–7 לספירה) היה באשדוד ים יישוב גדול ועשיר, ובו מבני ציבור, רחובות עמודים, נימפאון ונקרופוליס, והוא מתואר במפת מידבא. הרבאט שימש מבצר דתי-צבאי לשמירה על החוף.', 'חפירות IAA 1997-1999', ARRAY['https://archaeological.wixsite.com/ashdodyam/copy-of-introducing-ashdod-yam']::text[], NULL, 'archaeology', 'תב"ע 122/101/02/3', false, 'תיארוך: בטבלת הוועדה "1000 לספירה לערך", ובמקורות שנבדקו מבצר אומיי מסוף המאה ה-7 או ה-8.', '{}'::text[], NULL, NULL),
(17, 'ASH-017', 'גן אלישבע ואנדרטת חיל הים', 'גן אלישבע, רובע א׳', 'רובע א׳', '2061/111', false, 31.8092, 34.6406, NULL, false, NULL, false, 'פארק ואנדרטה', ARRAY['תקופה ישראלית']::text[], 'א', 'לאומית, היסטורית', 'עיריית אשדוד', 'קיים', 'פארק ואנדרטה', ARRAY['לאומית','היסטורית']::text[], 'גבוהה', 'מהפארקים העירוניים הגדולים והראשונים באשדוד, ברובע א׳ הוותיק. נקרא על שם אלישבע אשכול (לבית קפלן), פעילה ציונית ורעייתו של ראש הממשלה השלישי לוי אשכול. הנטיעות ואבן הפינה ב-27.5.1960, והגן נחנך ב-1967. בגן אנדרטת חיל הים.', 'בטקס ב-27.5.1960 הניח עובד בן-עמי את אבן הפינה, ושר האוצר לוי אשכול ובתו תמר נטעו את העצים הראשונים. הנטיעות נערכו בידי משרד העבודה וחברת אשדוד. בעיתון דבר נכתב: "הגן עתיד לסמל את הקשר בין העיר הצעירה לבין לוי אשכול, שנתן את ידו להקמתה". הגוף המנהל: עיריית אשדוד. מקור: ויקיפדיה, כפי שהוצג במצגת הוועדה.', NULL, ARRAY['https://he.wikipedia.org/wiki/גן_אלישבע']::text[], '6', 'committee_2016', NULL, false, 'גוש/חלקה 2061/111 זהים לרשומת בית קנדה.', '{}'::text[], NULL, 'הצעה אוטומטית – לאישור הוועדה'),
(19, 'ASH-019', 'אנדרטת סטרומה ומפקורה', 'רח׳ רוגוזין / משה דיין, רובע ד׳', 'חוף הים', '2076/175', false, 31.8, 34.638, NULL, false, NULL, false, 'אנדרטה', ARRAY['תקופה ישראלית']::text[], 'א', 'לאומית, היסטורית', 'עיריית אשדוד', 'קיים', 'אנדרטה', ARRAY['לאומית','היסטורית']::text[], 'גבוהה', 'אנדרטה לזכר ספינות המעפילים סטרומה ומפקורה. כלולה ברשימת הוועדה לשימור (2016), שהחליטה לכלול את כל האנדרטאות בעיר. פרטי ההקמה — לאימות.', NULL, NULL, '{}'::text[], '8', 'committee_2016', NULL, true, 'אזור: ברשימת הוועדה "מרינה", בטבלה "רובע ד׳".', '{}'::text[], NULL, 'הצעה אוטומטית – לאישור הוועדה'),
(25, 'ASH-025', 'מעגנות הנמל, תחנת הכוח אשכול ומפעל רוגוזין', 'חוף הים הצפוני, עורף הנמל', 'חוף הים', NULL, false, 31.8388, 34.6551, NULL, false, NULL, false, 'מתחם תעסוקה היסטורי', ARRAY['תקופה ישראלית']::text[], 'א', 'אדריכלית, לאומית', 'חנ"י / חברת החשמל / רמ"י', 'קיים', 'מתחם תעסוקה היסטורי', ARRAY['אדריכלית','לאומית']::text[], 'גבוהה', 'מתחם התעסוקה ההיסטורי של אשדוד, רשומה אחת כמו ברשימת הוועדה: שובר הגלים ומעגנות הנמל, תחנת הכוח אשכול ומפעל רוגוזין. מפעל רוגוזין: בית חרושת לטקסטיל וצמיגים מראשית אשדוד-ים, שנרכש בהמשך בידי חברת החשמל.', NULL, NULL, '{}'::text[], '21', 'committee_2016', NULL, true, NULL, ARRAY['נמל – שובר גלים ומעגנות','תחנת הכוח אשכול','מפעל רוגוזין']::text[], 'לפי פרסום מ-12.7.2020 מפעל רוגוזין נהרס והשטח נמסר למדינה. לאמת את המצב הקיים.', 'הצעה אוטומטית – לאישור הוועדה'),
(26, 'ASH-026', 'המרינה, המעגנות ופארק אשדוד־ים', 'חוף המרינה', 'חוף הים', NULL, false, 31.797, 34.632, NULL, false, NULL, false, 'מרינה ופארק', ARRAY['תקופה ישראלית']::text[], 'ב', 'נופית, אדריכלית', 'ממ"י / עיריית אשדוד', 'קיים', 'מרינה ופארק', ARRAY['נופית','אדריכלית']::text[], 'בינונית', 'מרקם חופי שהוועדה כללה בשימור: המרינה, המעגנות ופארק אשדוד-ים לאורך חוף המרינה.', NULL, NULL, '{}'::text[], NULL, 'texture', NULL, true, NULL, '{}'::text[], NULL, 'הצעה אוטומטית – לאישור הוועדה'),
(28, 'ASH-028', 'האתר האפיפליאוליתי', 'אזור הסיטי', 'רובעים ותיקים', NULL, false, 31.7925, 34.6385, NULL, false, NULL, false, 'אתר ארכאולוגי', ARRAY['תקופה פרהיסטורית']::text[], 'א', 'ארכאולוגית', 'לאימות (רשות העתיקות)', 'קיים', 'אתר ארכאולוגי', ARRAY['ארכאולוגית']::text[], 'גבוהה', 'האתר האחרון שנותר על דיונת חוף הים בארץ: יישוב גדול של ציידים ולקטים, תרבות נכחדת, מהתקופה האפיפליאוליתית, לפני 15,000–18,000 שנה. לפי מצגת הוועדה, יש לראות באתר נקודת ציון במערכת השטחים הפתוחים של אזור המרכז.', NULL, NULL, '{}'::text[], NULL, 'archaeology', NULL, true, 'בעלות ומיקום מדויק לאימות מול רשות העתיקות.', '{}'::text[], NULL, 'הצעה אוטומטית – לאישור הוועדה'),
(30, 'ASH-030', 'אחוזות הקברים', 'דרום העיר, ליד המצודה', 'חוף הים', NULL, false, 31.779, 34.624, NULL, false, NULL, false, 'אתר ארכאולוגי', ARRAY['תקופה ביזנטית']::text[], 'א', 'ארכאולוגית', 'לאימות (רשות העתיקות)', 'קיים', 'אתר ארכאולוגי', ARRAY['ארכאולוגית']::text[], 'גבוהה', 'אחוזות קברים עתיקות בדרום העיר, סמוך למצודת אשדוד ים. תחנה במסלול "טיילת בזמן".', 'לפי מצגת הוועדה: בתקופה הרומית והביזנטית (המאות 1–7 לספירה) היה באשדוד ים יישוב גדול ועשיר, ובו גם נקרופוליס.', NULL, '{}'::text[], NULL, 'archaeology', NULL, true, 'הזיהוי עם הנקרופוליס של אשדוד ים, בעלות ומיקום מדויק — לאימות.', '{}'::text[], NULL, 'הצעה אוטומטית – לאישור הוועדה'),
(31, 'ASH-031', 'הסוללה האשורית', 'דרום אשדוד, רצועת החוף', 'חוף הים', NULL, false, 31.776, 34.62, NULL, false, NULL, false, 'אתר ארכאולוגי', ARRAY['תקופת הברזל','תקופה פרסית-הלניסטית']::text[], 'א', 'ארכאולוגית', 'לאימות (רשות העתיקות)', 'קיים', 'אתר ארכאולוגי', ARRAY['ארכאולוגית']::text[], 'גבוהה', 'סוללה מתקופת הברזל ברצועת החוף בדרום העיר. על גבי הסוללה שרידי יישוב הלניסטי (332–162 לפנה״ס).', 'לפי מצגת הוועדה, דרום אשדוד על רצועת החוף הוא מאתרי תקופות הברונזה, הברזל והפרסית (2000–332 לפנה״ס): 3,000 שנות היסטוריה כנענית, ימי בית ראשון (פלשתים), האשורים, חורבן בית ראשון והתקופה הפרסית.', NULL, '{}'::text[], NULL, 'archaeology', NULL, true, 'בעלות ומיקום מדויק לאימות מול רשות העתיקות.', '{}'::text[], NULL, 'הצעה אוטומטית – לאישור הוועדה')
ON CONFLICT (site_no) DO UPDATE SET city_registry_id = EXCLUDED.city_registry_id, name = EXCLUDED.name, address = EXCLUDED.address, neighborhood = EXCLUDED.neighborhood, parcel = EXCLUDED.parcel, is_complex = EXCLUDED.is_complex, lat = EXCLUDED.lat, lng = EXCLUDED.lng, year_built = EXCLUDED.year_built, year_built_verified = EXCLUDED.year_built_verified, architect = EXCLUDED.architect, architect_verified = EXCLUDED.architect_verified, style = EXCLUDED.style, historical_periods = EXCLUDED.historical_periods, protection_level = EXCLUDED.protection_level, documentation_reason = EXCLUDED.documentation_reason, owner = EXCLUDED.owner, current_use = EXCLUDED.current_use, building_type = EXCLUDED.building_type, preservation_reasons = EXCLUDED.preservation_reasons, priority_level = EXCLUDED.priority_level, full_description = EXCLUDED.full_description, additional_info = EXCLUDED.additional_info, iaa_reference = EXCLUDED.iaa_reference, gov_sources = EXCLUDED.gov_sources, committee_no = EXCLUDED.committee_no, list_status = EXCLUDED.list_status, statutory_ref = EXCLUDED.statutory_ref, coords_approx = EXCLUDED.coords_approx, data_conflict = EXCLUDED.data_conflict, components = EXCLUDED.components, risk_note = EXCLUDED.risk_note, grade_note = EXCLUDED.grade_note, updated_at = now();

UPDATE shimur_buildings SET image_url = '/sites/committee/s17-gan-elisheva.jpg' WHERE site_no = 17 AND image_url IS NULL;
UPDATE shimur_buildings SET image_url = '/sites/committee/s25-eshkol.jpg' WHERE site_no = 25 AND image_url IS NULL;

INSERT INTO shimur_documents (kind, title, url, note, building_id)
SELECT 'image', v.title, v.url, 'מקור: מצגת הוועדה לשימור אתרים 2016', b.id
FROM (VALUES
(1, '/sites/committee/s01-night.jpg', 'המגדלור בלילה — מתוך מצגת הוועדה 2016'),
(2, '/sites/committee/s02-bridge.jpg', 'גשר עד הלום — מתוך מצגת הוועדה 2016'),
(14, '/sites/committee/s14-arches.jpg', 'שרידי המצודה — מתוך מצגת הוועדה 2016'),
(14, '/sites/committee/s14-aerial.jpg', 'המצודה וחוף הים ממעוף — מתוך מצגת הוועדה 2016'),
(14, '/sites/committee/s14-ruins.jpg', 'שרידי המצודה מול הים — מתוך מצגת הוועדה 2016'),
(17, '/sites/committee/s17-gan-elisheva.jpg', 'גן אלישבע, מבט מערבה מרחוב מקס נורדאו, 2025 — ויקיפדיה, כפי שהוצג במצגת הוועדה'),
(25, '/sites/committee/s25-eshkol.jpg', 'תחנת הכוח אשכול — צילום היסטורי מתוך מצגת הוועדה 2016')
) AS v(site_no, url, title)
JOIN shimur_buildings b ON b.site_no = v.site_no
WHERE NOT EXISTS (SELECT 1 FROM shimur_documents d WHERE d.url = v.url);

UPDATE shimur_routes SET description = 'מסלול לאורך החוף בין שכבות הזמן של אשדוד, מתקופת הברונזה ועד התקופה הערבית הקדומה. לפי מצגת הוועדה, יש לראות באתר האפיפליאוליתי נקודת ציון במערכת השטחים הפתוחים של אזור המרכז.', updated_at = now() WHERE slug = 'route-5';

INSERT INTO shimur_routes (slug, title, description, theme, is_public) VALUES
('route-6', 'אנדרטאות וזיכרון', 'הוועדה החליטה לכלול ברשימה את כל האנדרטאות בעיר. מסלול בין אתרי הזיכרון, מרובע א׳ ועד פארק עד הלום.', 'זיכרון', true),
('route-7', 'נחל לכיש — מהשפך ועד שדרת השקמים', 'לפי מקבץ נחל לכיש במצגת הוועדה: מהשפך לחוף הים במערב, עוטף את רובעי המגורים, עובר בסמוך לבית העלמין במזרח, עד פארק עד הלום — מתחם פנאי ונופש הסמוך לנחל, הכולל את האתרים ההיסטוריים מתקופת ראשית המדינה — וממשיך לשדרת השקמים בדרום.', 'נוף', true),
('route-8', 'חוף הים — מהמצודה ועד הנמל', 'לפי מקבץ חוף הים במצגת הוועדה: מחוף ט״ו והמצודה מדרום ועד שפך נחל לכיש, כולל מתחם התעסוקה ההיסטורי — מתקני הנמל, תחנת הכוח ומפעל רוגוזין בצפון.', 'חוף', true),
('route-9', 'שימור מול פיתוח — הרובעים הוותיקים', 'לפי מצגת הוועדה, שמירת מרקמים, אתרים נוספים וסביבתם תיבחן עם קידום תכניות אב להתחדשות עירונית ברובעים ב׳, ג׳, ה׳ ו־ו׳ ובמסגרת תכנית המתאר הכוללנית, כדוגמת "השוק" ברובע ב׳ ו"עץ השקמה" ברובע ו׳.', 'התחדשות', true)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO shimur_route_sites (route_id, building_id, position, narrative_text)
SELECT r.id, b.id, v.position, v.narrative_text
FROM (VALUES
('route-1', 9, 1, 'לשכת העבודה — המפגש הראשון של עולים חדשים עם מקום עבודה בעיר הצעירה.'),
('route-1', 10, 2, 'בית המלון הראשון שירת פקידים ומבקרים בתקופת הקמת הנמל.'),
('route-1', 4, 3, 'הקליפורניות — הבנקים הראשונים. תחילת הפעילות הכלכלית.'),
('route-1', 5, 4, 'בית קנדה — מרכז קליטה ברוטליסטי. כאן התחילו חייהם של אלפי עולים.'),
('route-1', 8, 5, 'הגן האדום — גן הילדים הראשון. כאן גדל הדור הראשון של ילדי אשדוד.'),
('route-1', 22, 6, 'מבנה העירייה הראשון ובריכת המים — משרדי העירייה הראשונים, בלב המרכז הרובעי.'),
('route-1', 21, 7, 'השיכון — מבנה אותנטי, מהשיכונים הראשונים בעיר.'),
('route-2', 13, 1, 'תל מור — יישוב עתיק בפי הנחל. מבצר מהברונזה המאוחרת שלט על כניסת הספינות.'),
('route-2', 14, 2, 'מצודת אשדוד ים — ריבאט אסלאמי וכנסיה ביזנטית. שכבות של תרבויות על חוף הים.'),
('route-2', 2, 3, 'גשר עד הלום — מהמאה ה-13 ועד 1948. כאן נעצרה ההתקדמות המצרית.'),
('route-2', 3, 4, 'האובליסק — סמל הפיוס. מצרים וישראל מנציחות יחד את זיכרון הקרב.'),
('route-2', 28, 5, 'האתר האפיפליאוליתי — האתר האחרון שנותר על דיונת חוף הים בארץ, לפני 15,000–18,000 שנה.'),
('route-3', 7, 1, 'המרכז הרובעי — הלב הפועם. קולונדה, עמודים, בריכת מים ציבורית. תכנון על פי עקרונות CIAM.'),
